detaileddescription.para:
Usage example: //Openanewfont
constsf::Fontfont("arial.ttf");

//Createatextwhichusesourfont
sf::Texttext1(font);
text1.setCharacterSize(30);
text1.setStyle(sf::Text::Regular);

//Createanothertextusingthesamefont,butwithdifferentparameters
sf::Texttext2(font);
text2.setCharacterSize(50);
text2.setStyle(sf::Text::Italic);
